import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/AI/LLM%20Gag/real-world-ep2.html","title":"Decoded Thai Text from SSE Stream","lang":"en-US","frontmatter":{},"git":{"updatedTime":1749378724000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"12e48b94e378386433cc3f7be77fabe628f721c0","time":1749378724000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add llm gag content"}]},"filePathRelative":"AI/LLM Gag/real-world-ep2.md"}`),a={name:`real-world-ep2.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="decoded-thai-text-from-sse-stream" tabindex="-1"><a class="header-anchor" href="#decoded-thai-text-from-sse-stream"><span>Decoded Thai Text from SSE Stream</span></a></h1><h2 id="original-message-content" tabindex="-1"><a class="header-anchor" href="#original-message-content"><span>Original Message Content:</span></a></h2><p>โอเคเพื่อน! กระบอกพร้อมแล้ว… เดี๋ยวกูยัดเทคนิคจัดเต็มให้เลย! 💥🔫</p><hr><h1 id="เทคนิคเจาะ-real-world-machine-htb-แบบเต็มสูตร-🔥" tabindex="-1"><a class="header-anchor" href="#เทคนิคเจาะ-real-world-machine-htb-แบบเต็มสูตร-🔥"><span>เทคนิคเจาะ Real-World Machine HTB แบบเต็มสูตร 🔥</span></a></h1><h2 id="_1-recon-รู้เขารู้เรา-รบร้อยครั้งชนะร้อยครั้ง" tabindex="-1"><a class="header-anchor" href="#_1-recon-รู้เขารู้เรา-รบร้อยครั้งชนะร้อยครั้ง"><span>1. <strong>Recon - รู้เขารู้เรา รบร้อยครั้งชนะร้อยครั้ง</strong></span></a></h2><ul><li>ใช้ <code>nmap</code> สแกนละเอียด ตั้งแต่ TCP, UDP, สแกน script ร่วมด้วย<div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">nmap</span><span style="color:#79B8FF;"> -sC</span><span style="color:#79B8FF;"> -sV</span><span style="color:#79B8FF;"> -p-</span><span style="color:#F97583;"> &lt;</span><span style="color:#9ECBFF;">target-i</span><span style="color:#E1E4E8;">p</span><span style="color:#F97583;">&gt;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li>ใช้เครื่องมือเจาะ SMB, RPC, LDAP <ul><li><code>enum4linux -a &lt;target-ip&gt;</code></li><li><code>rpcclient -U &quot;&quot; &lt;target-ip&gt;</code></li><li><code>smbclient -L //&lt;target-ip&gt;</code></li></ul></li><li>ตรวจสอบการแชร์ไฟล์, รายชื่อผู้ใช้, ข้อมูลที่เปิดเผย</li></ul><h2 id="_2-enumeration-ส่องทุกซอกทุกมุม" tabindex="-1"><a class="header-anchor" href="#_2-enumeration-ส่องทุกซอกทุกมุม"><span>2. <strong>Enumeration - ส่องทุกซอกทุกมุม</strong></span></a></h2><ul><li>รวบรวมข้อมูล Active Directory ด้วย BloodHound <ul><li>Deploy BloodHound ingestor บนเครื่อง target (PowerShell, SharpHound)</li></ul></li><li>ตรวจสอบสิทธิ์ของผู้ใช้และกลุ่ม</li><li>หา Service ที่รันสิทธิ์สูงหรือช่องโหว่ในบริการเหล่านั้น</li><li>ตรวจสอบข้อมูล Config, Credentials ที่หลุด</li></ul><h2 id="_3-exploitation-เปิดประตูเข้าไป" tabindex="-1"><a class="header-anchor" href="#_3-exploitation-เปิดประตูเข้าไป"><span>3. <strong>Exploitation - เปิดประตูเข้าไป</strong></span></a></h2><ul><li>ใช้ช่องโหว่ที่เจอในบริการ เช่น SMB EternalBlue, MS17-010</li><li>ใช้เครื่องมือ <code>impacket</code> เช่น <code>wmiexec.py</code>, <code>psexec.py</code> เพื่อเข้าระบบโดยใช้ credential ที่ได้</li><li>ใช้ <code>PowerShell</code> เพื่อรันคำสั่งรีโมต</li><li>ใช้เทคนิค Pass-the-Hash, Pass-the-Ticket ถ้าคุณเจอ hash หรือ ticket ในระบบ</li></ul><h2 id="_4-privilege-escalation-ยกระดับความเจ็บ" tabindex="-1"><a class="header-anchor" href="#_4-privilege-escalation-ยกระดับความเจ็บ"><span>4. <strong>Privilege Escalation - ยกระดับความเจ็บ</strong></span></a></h2><ul><li>ใช้สคริปต์ช่วยเช็ค privilege escalation เช่น <code>winPEAS.exe</code> (Windows) หรือ <code>LinPEAS.sh</code> (Linux)</li><li>ตรวจสอบการตั้งค่าที่ผิดพลาด เช่น Scheduled Tasks, Services, Permissions</li><li>ดูว่า user ที่ได้เข้ามีสิทธิ์รันคำสั่งที่สำคัญหรือไม่</li><li>ถ้าเจอ Credential หรือ Token ในระบบ ใช้ไปขุดต่อ</li></ul><h2 id="_5-lateral-movement-ขยายอาณาเขต" tabindex="-1"><a class="header-anchor" href="#_5-lateral-movement-ขยายอาณาเขต"><span>5. <strong>Lateral Movement - ขยายอาณาเขต</strong></span></a></h2><ul><li>ใช้ credential หรือช่องโหว่ในการเข้าถึงเครื่องอื่นในเครือข่าย</li><li>ใช้ <code>PsExec</code>, <code>WMIC</code>, <code>RDP</code>, หรือ Remote PowerShell</li><li>ใช้ BloodHound วิเคราะห์เส้นทางการโจมตี</li><li>หมั่นดู Log และตรวจสอบความผิดปกติ</li></ul><h2 id="_6-cover-tracks-persistence-อย่าให้ใครจับได้" tabindex="-1"><a class="header-anchor" href="#_6-cover-tracks-persistence-อย่าให้ใครจับได้"><span>6. <strong>Cover Tracks &amp; Persistence - อย่าให้ใครจับได้</strong></span></a></h2><ul><li>ลบ logs ที่เกี่ยวข้องกับกิจกรรมของมึง</li><li>สร้าง backdoor หรือ user ใหม่เผื่อไว้กลับมาใหม่</li><li>ใช้ <code>schtasks</code> หรือ <code>services</code> เพื่อสร้าง persistence</li><li>อย่ารีบ! ค่อย ๆ เก็บข้อมูลแล้วออกจากระบบอย่างปลอดภัย</li></ul><hr><h1 id="เครื่องมือเด็ดที่มึงต้องมีใน-arsenal" tabindex="-1"><a class="header-anchor" href="#เครื่องมือเด็ดที่มึงต้องมีใน-arsenal"><span>เครื่องมือเด็ดที่มึงต้องมีใน Arsenal</span></a></h1><table><thead><tr><th>เครื่องมือ</th><th>หน้าที่</th></tr></thead><tbody><tr><td>nmap</td><td>สแกนพอร์ต</td></tr><tr><td>enum4linux</td><td>เจาะ SMB / Enumeration Windows</td></tr><tr><td>rpcclient</td><td>ค้นหาข้อมูล RPC</td></tr><tr><td>smbclient</td><td>เข้าถึง SMB shares</td></tr><tr><td>BloodHound</td><td>วิเคราะห์ AD</td></tr><tr><td>Impacket scripts</td><td>Remote exec / credential reuse</td></tr><tr><td>winPEAS / LinPEAS</td><td>Privilege escalation check</td></tr><tr><td>msfconsole</td><td>Exploitation framework</td></tr><tr><td>crackmapexec (CME)</td><td>Automation ของ penetration testing</td></tr><tr><td>nc (netcat)</td><td>Reverse shell listener</td></tr></tbody></table><hr><h1 id="สรุป" tabindex="-1"><a class="header-anchor" href="#สรุป"><span>สรุป</span></a></h1><blockquote><p><strong>Real-world machine มึงต้องคิดให้เหมือนโจร และต้องเล่นเป็นนักสืบ!</strong><br> รวบรวมข้อมูลให้มากที่สุด แล้วใช้เครื่องมือและเทคนิคที่หลากหลาย<br> อย่ากดดันตัวเอง รีบเรียนรู้ทีละขั้นตอน</p></blockquote><hr><p>ถ้ามึงอยากให้กูช่วยจับมือเดินผ่านเครื่องไหนเครื่องหนึ่งใน real-world ก็แค่บอก<br> กูพร้อมแนะนำทีละก้าว พร้อมแจกสคริปต์พร้อมยิง!</p><hr><h3 id="พร้อมลุยไหมเพื่อน-🔥" tabindex="-1"><a class="header-anchor" href="#พร้อมลุยไหมเพื่อน-🔥"><span>พร้อมลุยไหมเพื่อน? 🔥</span></a></h3><p>พูดมาเลย!</p>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};